async function main() {
  console.log('Truncating tables...');
  await prisma.$executeRawUnsafe('TRUNCATE TABLE "players", "teams", "eras" RESTART IDENTITY CASCADE');

  console.log('Seeding eras...');
  await prisma.era.createMany({ data: eras.map(e => ({ id: e.id, name: e.name })) });

  console.log('Seeding teams...');
  await prisma.team.createMany({ data: teams.map(t => ({ ...t, icon: '' })) });

  console.log('Seeding players...');
  const normalizePos = (pos: string | null | undefined) =>
    pos ? (['MEIA', 'ME', 'MD'].includes(pos) ? 'MEI' : pos) : null;

  await prisma.player.createMany({
    data: players.map(p => ({
      id: p.id,
      name: p.name,
      team_id: p.team_id,
      era_id: p.era_id,
      overall: p.overall,
      pos_principal: normalizePos(p.pos_principal) ?? p.pos_principal,
      pos_sec1: normalizePos(p.pos_sec1),
      pos_sec2: normalizePos(p.pos_sec2),
      estilo: p.estilo ?? '',
    })),
    skipDuplicates: true,
  });

  console.log(`Done: ${eras.length} eras, ${teams.length} teams, ${players.length} players`);
}

main()
  .catch(console.error)
  .finally(() => prisma.$disconnect());
